"""Elevator as an explicit state machine.
The Elevator owns its state and ALL transition rules (in step()).
The Controller only decides which car answers a hall call.
"""
from enum import Enum, auto


class State(Enum):
    IDLE = auto()
    MOVING_UP = auto()
    MOVING_DOWN = auto()
    DOOR_OPEN = auto()


class Elevator:
    def __init__(self, elevator_id: int, floor: int = 0):
        self.elevator_id = elevator_id
        self.floor = floor
        self.state = State.IDLE
        self.targets = set()
        self.history = []            # (floor, state) after each step, for tests

    def request(self, floor: int) -> None:
        if floor != self.floor:
            self.targets.add(floor)

    def distance_to(self, floor: int) -> int:
        return abs(self.floor - floor)

    def step(self) -> None:
        """One tick, one transition. Every legal state change lives here --
        there is no other way for the elevator to move or open doors."""
        if self.state in (State.DOOR_OPEN, State.IDLE):
            self.state = self._resume()
        elif self.state is State.MOVING_UP:
            self.floor += 1
            self._maybe_stop()
        elif self.state is State.MOVING_DOWN:
            self.floor -= 1
            self._maybe_stop()
        self.history.append((self.floor, self.state))

    def _resume(self) -> State:
        if not self.targets:
            return State.IDLE
        nearest = min(self.targets, key=self.distance_to)
        return State.MOVING_UP if nearest > self.floor else State.MOVING_DOWN

    def _maybe_stop(self) -> None:
        if self.floor in self.targets:
            self.targets.discard(self.floor)
            self.state = State.DOOR_OPEN


class ElevatorController:
    """Dispatch policy: nearest car wins. To change the policy you swap THIS
    class -- Elevator itself never changes. That is the extensibility seam."""
    def __init__(self, elevators):
        self.elevators = list(elevators)

    def call(self, floor: int) -> Elevator:
        car = min(self.elevators, key=lambda e: e.distance_to(floor))
        car.request(floor)
        return car

    def tick(self) -> None:
        for e in self.elevators:
            e.step()


# ---- demo + self-checks ----------------------------------------------------
a, b = Elevator(1, floor=0), Elevator(2, floor=8)
ctl = ElevatorController([a, b])

assert ctl.call(2) is a              # floor 0 is nearer to 2 than floor 8
assert ctl.call(7) is b              # floor 8 is nearer to 7

for _ in range(4):
    ctl.tick()

assert a.floor == 2 and b.floor == 7
assert State.DOOR_OPEN in [s for _, s in a.history]   # it stopped, not teleported
assert State.MOVING_DOWN in [s for _, s in b.history] # b went DOWN to 7

ctl.tick()                            # nothing left to do
assert a.state is State.IDLE and b.state is State.IDLE
print("elevator OK -- a:", a.history)

"""Splitwise core: a SplitStrategy decides who owes what for one expense;
the Ledger keeps net balances; simplify() settles them with a greedy
max-debtor -> max-creditor match. Money is integer paise -- never float.
"""
from abc import ABC, abstractmethod


class User:
    def __init__(self, name: str):
        self.name = name

    def __repr__(self):
        return self.name


class SplitStrategy(ABC):
    @abstractmethod
    def shares(self, amount: int, participants) -> dict: ...


class EqualSplit(SplitStrategy):
    def shares(self, amount, participants):
        n = len(participants)
        base, rem = divmod(amount, n)
        # the first `rem` people absorb one leftover paisa each -> sums exactly
        return {u: base + (1 if i < rem else 0)
                for i, u in enumerate(participants)}


class ExactSplit(SplitStrategy):
    def __init__(self, exact: dict):          # {user: paise}
        self.exact = exact

    def shares(self, amount, participants):
        assert sum(self.exact.values()) == amount, "exact shares must add up"
        return dict(self.exact)


class Ledger:
    """net[user] > 0 means the group owes this user; < 0 means they owe."""
    def __init__(self):
        self.net = {}

    def add_expense(self, paid_by, amount, participants,
                    strategy: SplitStrategy):
        shares = strategy.shares(amount, participants)
        self.net[paid_by] = self.net.get(paid_by, 0) + amount
        for user, share in shares.items():
            self.net[user] = self.net.get(user, 0) - share

    def simplify(self):
        """Greedy settle: biggest debtor pays biggest creditor, repeat.
        Produces at most n-1 transfers for n people with nonzero balance."""
        debtors = sorted((u for u in self.net if self.net[u] < 0),
                         key=lambda u: self.net[u])          # most negative first
        creditors = sorted((u for u in self.net if self.net[u] > 0),
                           key=lambda u: -self.net[u])       # most positive first
        owed = dict(self.net)
        transfers = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            d, c = debtors[i], creditors[j]
            pay = min(-owed[d], owed[c])
            transfers.append((d, c, pay))
            owed[d] += pay
            owed[c] -= pay
            if owed[d] == 0:
                i += 1
            if owed[c] == 0:
                j += 1
        return transfers


# ---- demo + self-checks ----------------------------------------------------
A, B, C = User("Asha"), User("Bala"), User("Chen")
ledger = Ledger()
ledger.add_expense(A, 30000, [A, B, C], EqualSplit())   # Rs 300 dinner, 3 ways
ledger.add_expense(B, 12000, [B, C], EqualSplit())      # Rs 120 cab, 2 ways
assert sum(ledger.net.values()) == 0                    # ledger invariant: always

# Asha +30000-10000=+20000; Bala +12000-10000-6000=-4000; Chen -10000-6000=-16000
assert ledger.net[A] == 20000
assert ledger.net[B] == -4000
assert ledger.net[C] == -16000

transfers = ledger.simplify()
assert transfers == [(C, A, 16000), (B, A, 4000)]       # 2 payments settle all
assert len(transfers) <= 2                              # <= n-1 for n=3 users

# odd amount: 100 paise among 3 -> 34+33+33, still sums exactly
odd = EqualSplit().shares(100, [A, B, C])
assert sum(odd.values()) == 100 and sorted(odd.values()) == [33, 33, 34]
print("settled:", [(d.name, c.name, p) for d, c, p in transfers])

import threading
"""BookMyShow core problem: two users click the same seat in the same
second. Fix: a short-lived exclusive lock per seat (with a TTL, a time-to-
live after which the lock expires on its own), then payment, then BOOKED.
The Clock is injected so expiry is testable without sleeping.
"""
from enum import Enum, auto


class Clock:
    def __init__(self):
        self.t = 0.0

    def now(self):
        return self.t

    def advance(self, secs):
        self.t += secs


class SeatStatus(Enum):
    AVAILABLE = auto()
    BOOKED = auto()
    # note: LOCKED is NOT a seat status -- locks live in SeatLockManager,
    # so an expired lock never leaves a seat stuck in a wrong state.


class Seat:
    def __init__(self, seat_id: str):
        self.seat_id = seat_id
        self.status = SeatStatus.AVAILABLE


class SeatLock:
    def __init__(self, seat, user, locked_at, ttl):
        self.seat, self.user = seat, user
        self.expires_at = locked_at + ttl

    def is_expired(self, now):
        return now >= self.expires_at


class SeatLockManager:
    """Owns ALL locking rules. No other class touches locks."""
    def __init__(self, clock: Clock, ttl_secs: float = 300):
        # One mutex makes check-then-set atomic IN THIS PROCESS — see prose caveat.
        self._mutex = threading.Lock()
        self.clock, self.ttl = clock, ttl_secs
        self.locks = {}                       # seat_id -> SeatLock

    def lock(self, seat, user) -> bool:
        # Serialise check-then-set — without this, two threads both pass the
        # availability check and both "acquire" the seat.
        with self._mutex:
            return self._lock_unlocked(seat, user)

    def _lock_unlocked(self, seat, user) -> bool:
        existing = self.locks.get(seat.seat_id)
        if existing and not existing.is_expired(self.clock.now()):
            return existing.user == user      # already yours -> ok, else refuse
        if seat.status is SeatStatus.BOOKED:
            return False
        self.locks[seat.seat_id] = SeatLock(seat, user, self.clock.now(), self.ttl)
        return True

    def holds_lock(self, seat, user) -> bool:
        # Serialise check-then-set — without this, two threads both pass the
        # availability check and both "acquire" the seat.
        with self._mutex:
            return self._holds_lock_unlocked(seat, user)

    def _holds_lock_unlocked(self, seat, user) -> bool:
        lk = self.locks.get(seat.seat_id)
        return bool(lk and lk.user == user
                    and not lk.is_expired(self.clock.now()))

    def release(self, seat):
        # Serialise the critical section — without this, two threads both pass the
        # availability check and both "acquire" the seat (demonstrated in review).
        with self._mutex:
            return self._release_unlocked(seat)

    def _release_unlocked(self, seat):
        self.locks.pop(seat.seat_id, None)


class BookingService:
    def __init__(self, lock_manager: SeatLockManager):
        self.lock_manager = lock_manager
        self.bookings = []

    def hold(self, seats, user) -> bool:
        """All-or-nothing: if any seat fails, release the ones we grabbed."""
        got = []
        for seat in seats:
            if not self.lock_manager.lock(seat, user):
                for s in got:
                    self.lock_manager.release(s)
                return False
            got.append(seat)
        return True

    def confirm(self, seats, user) -> bool:   # called after payment succeeds
        if not all(self.lock_manager.holds_lock(s, user) for s in seats):
            return False                      # lock expired mid-payment -> refuse
        for seat in seats:
            seat.status = SeatStatus.BOOKED
            self.lock_manager.release(seat)
        self.bookings.append((user, [s.seat_id for s in seats]))
        return True


# ---- demo + self-checks ----------------------------------------------------
clock = Clock()
seats = {sid: Seat(sid) for sid in ("A1", "A2", "A3")}
service = BookingService(SeatLockManager(clock, ttl_secs=300))

assert service.hold([seats["A1"], seats["A2"]], "asha")
assert not service.hold([seats["A3"], seats["A2"]], "bala")  # A2 taken
assert "A3" not in service.lock_manager.locks     # rollback released A3

clock.advance(301)                                # asha never paid; TTL passed
assert service.hold([seats["A2"], seats["A3"]], "bala")
assert not service.confirm([seats["A1"], seats["A2"]], "asha")  # locks expired
assert service.confirm([seats["A2"], seats["A3"]], "bala")
assert seats["A2"].status is SeatStatus.BOOKED
assert not service.hold([seats["A2"]], "chen")    # booked seats stay booked
assert service.hold([seats["A1"]], "chen")        # A1 free again after expiry
print("bookings:", service.bookings)

"""Two patterns doing two different jobs:
Observer  -- WHO gets told when an event happens (publish/subscribe).
Strategy  -- HOW one message is delivered (email vs SMS), chosen per user.
"""
from abc import ABC, abstractmethod


class Channel(ABC):                      # Strategy interface
    @abstractmethod
    def send(self, to_user, text): ...


class EmailChannel(Channel):
    def __init__(self):
        self.sent = []

    def send(self, to_user, text):
        self.sent.append((to_user.email, text))


class SmsChannel(Channel):
    def __init__(self):
        self.sent = []

    def send(self, to_user, text):
        self.sent.append((to_user.phone, text))


class User:
    def __init__(self, name, email, phone, preferred: str):
        self.name, self.email, self.phone = name, email, phone
        self.preferred = preferred       # "email" | "sms"


class Observer(ABC):
    @abstractmethod
    def on_event(self, event_type, payload): ...


class EventBus:
    """Observer pattern's subject: publishers do not know their listeners."""
    def __init__(self):
        self.subscribers = {}            # event_type -> [Observer]

    def subscribe(self, event_type, observer: Observer):
        self.subscribers.setdefault(event_type, []).append(observer)

    def publish(self, event_type, payload):
        for obs in self.subscribers.get(event_type, []):
            obs.on_event(event_type, payload)


class NotificationService(Observer):
    """An Observer of business events that picks a Strategy per user."""
    def __init__(self, channels: dict, users):
        self.channels = channels         # name -> Channel
        self.users = users

    def on_event(self, event_type, payload):
        for user in self.users:
            channel = self.channels[user.preferred]   # Strategy lookup
            channel.send(user, f"[{event_type}] {payload}")


class AuditLog(Observer):
    """Second observer: added WITHOUT touching EventBus or NotificationService.
    That is the Open/Closed principle doing real work."""
    def __init__(self):
        self.rows = []

    def on_event(self, event_type, payload):
        self.rows.append(event_type)


# ---- demo + self-checks ----------------------------------------------------
email, sms = EmailChannel(), SmsChannel()
users = [User("Asha", "asha@example.com", "111", "email"),
         User("Bala", "bala@example.com", "222", "sms")]
notifier = NotificationService({"email": email, "sms": sms}, users)
audit = AuditLog()

bus = EventBus()
bus.subscribe("order_shipped", notifier)
bus.subscribe("order_shipped", audit)

bus.publish("order_shipped", "order #42 left the warehouse")

assert email.sent == [("asha@example.com",
                       "[order_shipped] order #42 left the warehouse")]
assert sms.sent == [("222", "[order_shipped] order #42 left the warehouse")]
assert audit.rows == ["order_shipped"]

bus.publish("price_drop", "wishlist item")    # no subscribers -> no crash
assert len(email.sent) == 1 and len(sms.sent) == 1
print("notification OK")

"""Snake & Ladder. The Board owns jump rules; the Dice is injected (a
LoadedDice in tests makes the game deterministic); the Game owns only the
turn loop. New rules become new small classes, not edits to old ones.
"""
import random


class Jump:
    def __init__(self, start: int, end: int):
        self.start, self.end = start, end


class Snake(Jump):
    def __init__(self, head: int, tail: int):
        assert tail < head, "a snake must move you DOWN"
        super().__init__(head, tail)


class Ladder(Jump):
    def __init__(self, bottom: int, top: int):
        assert top > bottom, "a ladder must move you UP"
        super().__init__(bottom, top)


class Board:
    def __init__(self, size: int, jumps):
        self.size = size
        self.jumps = {}                   # cell -> destination cell
        for j in jumps:
            assert j.start not in self.jumps, "one jump per cell"
            self.jumps[j.start] = j.end

    def next_position(self, pos: int, roll: int) -> int:
        target = pos + roll
        if target > self.size:            # overshoot rule: stay put
            return pos
        return self.jumps.get(target, target)


class Dice:
    def __init__(self, sides: int = 6, rng=random):
        self.sides, self.rng = sides, rng

    def roll(self) -> int:
        return self.rng.randint(1, self.sides)


class LoadedDice(Dice):
    """Deterministic rolls -> deterministic tests. THIS is why Dice is a
    class and not a bare random.randint call inside Game."""
    def __init__(self, rolls):
        self.rolls = list(rolls)
        self.i = 0

    def roll(self) -> int:
        v = self.rolls[self.i % len(self.rolls)]
        self.i += 1
        return v


class Player:
    def __init__(self, name: str):
        self.name, self.pos = name, 0


class Game:
    def __init__(self, board: Board, dice: Dice, players):
        self.board, self.dice = board, dice
        self.players = list(players)
        self.winner = None

    def play_turn(self, player: Player) -> None:
        roll = self.dice.roll()
        player.pos = self.board.next_position(player.pos, roll)
        if player.pos == self.board.size:
            self.winner = player

    def play(self, max_turns: int = 1000):
        for turn in range(max_turns):
            self.play_turn(self.players[turn % len(self.players)])
            if self.winner:
                return self.winner
        return None


# ---- demo + self-checks ----------------------------------------------------
board = Board(20, [Ladder(3, 15), Snake(17, 4)])
assert board.next_position(0, 3) == 15        # ladder climbs
assert board.next_position(15, 2) == 4        # snake bites
assert board.next_position(19, 4) == 19       # overshoot: stay put

asha, bala = Player("Asha"), Player("Bala")
game = Game(board, LoadedDice([3, 2, 5]), [asha, bala])
winner = game.play()
# Asha: 3 -> ladder -> 15, Bala: 2, Asha: 15+5 = 20 -> wins
assert winner is asha and asha.pos == 20 and bala.pos == 2

bad_snake_rejected = False
try:
    Snake(4, 17)                              # upward "snake" must be rejected
except AssertionError:
    bad_snake_rejected = True
assert bad_snake_rejected
print("winner:", winner.name)
